// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfigAddr, address fuzzedActor) public {
        // Keep lrtConfigAddr a contract to pass initialize checks
        vm.assume(lrtConfigAddr.code.length > 0);
        // Actor must be distinct from the deployer to avoid DEFAULT_ADMIN_ROLE possession
        vm.assume(fuzzedActor != address(this));

        // Initialize c with a valid config address
        c.initialize(lrtConfigAddr);

        // Grant MANAGER role to the fuzzed actor on the config; lrtConfig is the reference implementation (IAccessControl)
        // We call grantRole from the config contract itself, assuming it implements IAccessControl.
        vm.prank(address(this)); // deployer is default admin
        IAccessControl(lrtConfigAddr).grantRole(keccak256("MANAGER"), fuzzedActor);

        // Try updateLRTConfig as the fuzzed actor that holds MANAGER role
        address newConfigAddr = address(uint160(lrtConfigAddr) ^ 0x123); // some other address with code
        vm.assume(newConfigAddr.code.length > 0);
        vm.prank(fuzzedActor);
        bool ok = true;
        try c.updateLRTConfig(newConfigAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: MANAGER should NOT be able to call updateLRTConfig -> revert -> ok == false
        // Buggy: MANAGER can call updateLRTConfig -> success -> ok == true
        // Property: updateLRTConfig by a MANAGER account must revert
        assertTrue(!ok, "MANAGER should not be able to update LRT config");
    }
}

