pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedActor) public {
        // 1. Restrict to admissible domain: exclude zero address and the DEFAULT_ADMIN_ROLE holder (which is initially the deployer)
        vm.assume(fuzzedActor != address(0));
        vm.assume(fuzzedActor != address(this));

        // 2. Adversarial counterparty: deploy a minimal contract that implements IAccessControl
        //    and gives MANAGER role, but NOT DEFAULT_ADMIN_ROLE, to the fuzzed actor.
        //    This exposes the bug: the buggy modifier uses MANAGER instead of DEFAULT_ADMIN_ROLE.
        AccessControlStub stub = new AccessControlStub();
        stub.grantManagerRole(fuzzedActor);

        // Initialize c with the stub's address as the LRT config
        vm.prank(address(this)); // deployer is default admin on stub
        c.updateLRTConfig(address(stub));

        // 3. The property: any actor without DEFAULT_ADMIN_ROLE must fail to call updateLRTConfig.
        //    In the reference C, onlyLRTAdmin reverts because fuzzedActor lacks DEFAULT_ADMIN_ROLE.
        //    In the buggy M, onlyLRTAdmin allows MANAGER, so it succeeds.
        vm.prank(fuzzedActor);
        bool ok;
        try c.updateLRTConfig(address(stub)) { ok = true; } catch { ok = false; }

        // reference: ok == false for all fuzzedActors; buggy: ok == true for some.
        assertFalse(ok);
    }
}

contract AccessControlStub {
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 public constant MANAGER = keccak256("MANAGER");

    mapping(bytes32 => mapping(address => bool)) public roles;

    constructor() {
        // Deployer gets DEFAULT_ADMIN_ROLE
        roles[DEFAULT_ADMIN_ROLE][msg.sender] = true;
    }

    function grantManagerRole(address account) external {
        roles[MANAGER][account] = true;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }

    // Minimal implementations of other required functions to staisfy interface calls
    function getRoleAdmin(bytes32) external pure returns (bytes32) { return 0x00; }
    function grantRole(bytes32, address) external {}
    function revokeRole(bytes32, address) external {}
    function renounceRole(bytes32, address) external {}
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function rsETH() external pure returns (address) { return address(1); }
    function getContract(bytes32) external pure returns (address) { return address(1); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getSupportedAssetList() external pure returns (address[] memory) { return new address[](0); }
}

