pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract so lrtConfig is set and role checks work.
        // We deploy a minimal config that implements IAccessControl for hasRole.
        address lrtConfig = address(new MockLRTConfig());
        c.initialize(lrtConfig);
    }

    function testFuzz_property(address caller, address newConfig, bool callerIsAdmin, bool callerIsManager) public {
        // Restrict to EOA-like callers (no code) to avoid precompile interference.
        vm.assume(caller.code.length == 0);
        // Ensure newConfig is a non-zero address and not the current lrtConfig.
        vm.assume(newConfig != address(0));
        vm.assume(newConfig != address(c.lrtConfig()));

        // Set up roles for the caller in our mock config.
        MockLRTConfig config = MockLRTConfig(address(c.lrtConfig()));
        config.setRole(bytes32(0x00), caller, callerIsAdmin);       // DEFAULT_ADMIN_ROLE
        config.setRole(keccak256("MANAGER"), caller, callerIsManager);

        vm.prank(caller);
        bool ok;
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference rule: if the caller is NOT admin, the call must revert.
        // Bug: if callerIsManager is true and callerIsAdmin is false, the buggy version succeeds (ok == true),
        // violating the rule.
        if (!callerIsAdmin) {
            assertTrue(!ok, "Non-admin should not be able to update config");
        } else {
            // Optional: If caller is admin, call may succeed or fail depending on other checks,
            // but that's not where the bug manifests. We can just assert nothing here,
            // but the previous if-branch is the discriminating one.
            // To keep a single assertTrue, we can assert a tautology that holds for reference
            // but also holds for buggy when admin succeeds.
            // However, the property must pass reference for ALL inputs and fail for buggy for SOME.
            // We need a single assertion that captures the rule.
            // Let's combine: for all callers, if (caller is not admin) -> revert.
            // Equivalently: ok -> callerIsAdmin.
            // So we can assert: !ok || callerIsAdmin.
            // This passes reference always, and fails buggy when callerIsManager=true, callerIsAdmin=false, ok=true.
        }

        // Single assertion:
        assertTrue(!ok || callerIsAdmin, "Non-admin caller succeeded in updating config");
    }
}

contract MockLRTConfig {
    mapping(address => mapping(bytes32 => bool)) public roles;

    function setRole(bytes32 role, address account, bool granted) external {
        roles[account][role] = granted;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[account][role];
    }

    // Stub other functions needed by C or the test
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function rsETH() external pure returns (address) { return address(0); }
    function getContract(bytes32) external pure returns (address) { return address(0); }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
}

