pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newConfig, address admin) public {
        vm.assume(newConfig != address(0));
        vm.assume(admin != address(0) && admin != newConfig);

        // Both the reference and buggy modifier use the same DEFAULT_ADMIN_ROLE (0x00) as LRT admin.
        // The reference grants the default admin role to `admin`, the bug does not.
        // However, we cannot directly manipulate AccessControl role storage without deploying a mock.
        // Since the modifier `onlyLRTAdmin` checks the role via `lrtConfig.hasRole(0x00, msg.sender)`,
        // we can fuzz the admin address and ensure the behavior branching is triggered.
        // The difference: the reference modifier uses `bytes32(0)` as the admin role, which is the standard DEFAULT_ADMIN_ROLE.
        // The buggy modifier uses `keccak256("WRONG_ROLE")` instead of `0x00`.
        // In a real LRTConfig, only the actual DEFAULT_ADMIN_ROLE (0x00) would pass the check.
        // We deploy a minimal LRTConfig mock that has a `hasRole` function returning true only for the correct role.
        // This ensures the reference succeeds and the bug fails when called by the admin.
        LRTConfigMock configMock = new LRTConfigMock();
        // Initialize C with the mock's address. We must be the zero address (or deployer) that has admin role in the mock?
        // Actually, AccessControl is not inherited in mock, we just hardcode hasRole to return true for 0x00 role and admin address.
        // The mock is deployed and its address is used as lrtConfig.
        // The `initialize` of C sets lrtConfig to the supplied address. Only the _initializer can call it once.
        c.initialize(address(configMock));

        // The reference modifier checks hasRole(0x00, msg.sender). Our mock returns true for 0x00 and `admin`.
        // The buggy modifier checks hasRole(keccak256("WRONG_ROLE"), msg.sender). Our mock returns false for that role.
        // So when `admin` calls updateLRTConfig, the reference will succeed, updating lrtConfig to `newConfig`.
        // The buggy will revert, leaving lrtConfig unchanged.

        vm.prank(admin);
        // We need to call updateLRTConfig with a valid non-zero address.
        // The reference updates lrtConfig, the bug reverts.
        bool ok = false;
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assertion: If the update succeeded (no revert), the lrtConfig should be newConfig.
        // For the reference, ok will be true and lrtConfig updated. For the bug, ok will be false.
        // We can assert: ok => address(c.lrtConfig()) == newConfig.
        // But the bug will never satisfy the implication because ok is false, making implication trivially true.
        // Better: assert that the reference always succeeds and the bug always fails for the admin.
        // Since we need a single assertion that reads c's public surface and passes for reference, fails for bug.
        // We check: address(c.lrtConfig()) == newConfig (reference will have it updated, bug will still have old mock address).
        assertTrue(address(c.lrtConfig()) == newConfig);
    }
}

contract LRTConfigMock {
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // Only DEFAULT_ADMIN_ROLE (0x00) returns true, others false.
        // This simulates a config where DEFAULT_ADMIN_ROLE is granted to the fuzzed admin.
        // The reference modifier uses 0x00, bug uses keccak256("WRONG_ROLE").
        // Both calls are made by the same pranked admin, so the check on role is the difference.
        // However, hasRole also checks account. The modifier uses msg.sender.
        // We need to ensure that for the pranked admin, hasRole returns true when role is 0x00.
        if (role == bytes32(0)) {
            return true;
        }
        return false;
    }

    // ILRTConfig stubs
    function rsETH() external view returns (address) { return address(0); }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function isSupportedAsset(address) external view returns (bool) { return false; }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
    function getContract(bytes32) external view returns (address) { return address(0); }
    function getSupportedAssetList() external view returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address) external view returns (uint256) { return 0; }
}

