pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, address newLRTConfig) public {
        // Restrict to plausible addresses
        vm.assume(admin != address(0));
        vm.assume(newLRTConfig != address(0));
        vm.assume(admin != newLRTConfig);

        // Initialize the contract with a dummy LRT config that will grant the DEFAULT_ADMIN_ROLE
        // The contract's onlyLRTAdmin modifier checks `hasRole(0x00, msg.sender)` on the stored lrtConfig.
        // We need a real IAccessControl that returns `true` for the admin role.
        AdminConfig config = new AdminConfig(admin);
        c.initialize(address(config));

        // Now call updateLRTConfig as the admin; the reference should succeed, the buggy one should revert.
        vm.prank(admin);
        bool success;
        try c.updateLRTConfig(newLRTConfig) {
            success = true;
        } catch {
            success = false;
        }

        // The property: either the call succeeded AND lrtConfig was updated to newLRTConfig,
        // OR it failed AND lrtConfig is still the old one (address(config)).
        // The reference always succeeds, so success is true and updated.
        // The buggy version always fails, so success is false and lrtConfig is unchanged.
        bool updated = address(c.lrtConfig()) == newLRTConfig;
        bool unchanged = address(c.lrtConfig()) == address(config);
        assertTrue((success && updated) || (!success && unchanged));
    }
}

// Minimal IAccessControl that grants the zero-bytes32 DEFAULT_ADMIN_ROLE to `admin`.
contract AdminConfig {
    address public immutable admin;

    constructor(address _admin) {
        admin = _admin;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        // DEFAULT_ADMIN_ROLE is 0x00...00
        if (role == bytes32(0) && account == admin) {
            return true;
        }
        return false;
    }

    // Dummy stubs to satisfy the interface
    function getRoleAdmin(bytes32) external pure returns (bytes32) { return bytes32(0); }
    function grantRole(bytes32, address) external {}
    function revokeRole(bytes32, address) external {}
    function renounceRole(bytes32, address) external {}

    function rsETH() external view returns (address) {
        // Not used in the modifier but needed by the contract's internal logic in some paths;
        // return a non-zero address to avoid potential revert in getRsETHAmountToMint etc.
        return address(this);
    }

    function isSupportedAsset(address) external pure returns (bool) { return false; }
}

