contract InvMutTest is Test {
    C c;
    address admin;
    address newLrtConfig;

    function setUp() public {
        c = new C();
        // Use precompiled addresses to avoid zero-address issues; admin and newLrtConfig are fuzzed
        admin = address(0x123);
        newLrtConfig = address(0x456);
    }

    function testFuzz_property(address adminAddr, address newConfigAddr) public {
        // Restrict domain: addresses must not be zero (UtilLib.checkNonZeroAddress reverts on zero)
        vm.assume(adminAddr != address(0));
        vm.assume(newConfigAddr != address(0));

        // Grant DEFAULT_ADMIN_ROLE to adminAddr on a mock LRT config (the initial lrtConfig must support IAccessControl)
        // We deploy a minimal config mock that implements IAccessControl for hasRole
        MockLRTConfig mockConfig = new MockLRTConfig(adminAddr);

        // Initialize C with the mock config address
        c.initialize(address(mockConfig));

        // Admin calls updateLRTConfig
        vm.prank(adminAddr);
        bool success = true;
        try c.updateLRTConfig(newConfigAddr) {
            // success
        } catch {
            success = false;
        }

        // Assertion: If the caller has DEFAULT_ADMIN_ROLE (which adminAddr does in the mock),
        // the reference contract C updates lrtConfig to newConfigAddr, so the call succeeds.
        // The buggy version always reverts because the modifier checks a wrong role hash,
        // so success will be false. The reference contract must satisfy: for any non-zero admin with the role,
        // the call succeeds and lrtConfig is updated.
        assertTrue(success && address(c.lrtConfig()) == newConfigAddr);
    }
}

