// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address newConfig) public {
        // The bug manifests only through the behavior of an external party that answers
        // hasRole(DEFAULT_ADMIN_ROLE, caller) with false for the caller. A raw fuzzed address
        // is an EOA with no code, so calls to it always succeed. We deploy a minimal helper that
        // acts as a config contract returning false for hasRole, so that the onlyLRTAdmin modifier
        // triggers the revert path in the reference and allows the call in the mutant.
        // The fuzzer still picks the caller and the new config address.
        vm.assume(caller != address(0));
        vm.assume(newConfig != address(0));
        vm.assume(caller != newConfig);

        // Deploy an adversarial lrtConfig that denies admin role to everyone
        AdversarialConfig advConfig = new AdversarialConfig();

        // Initialize C with the adversarial config; we need the role check to happen inside
        // the modifier, which reads from c.lrtConfig().hasRole(...). Since we cannot use the
        // role-grant mechanism without a real access control, we replace the config with our helper
        // that always returns false for hasRole.
        // To call updateLRTConfig, we need c to be initialized first.
        // We mimic a legitimate initialization by calling initialize with a compliant config,
        // then we call updateLRTConfig with the adversarial config as the target.
        // However, the test must drive through `updateLRTConfig` as the entry point.
        // We deploy a temporary config that supports initialization, then call updateLRTConfig
        // to set the adversarial config.

        // Setup: initialize with a benign config that gives the test contract admin rights
        // so we can call updateLRTConfig. But the property we test is about the updateLRTConfig
        // function itself when called by a non-admin. After initialization, we switch to the
        // adversarial config using a pranked admin call (the initial benign config gives us admin).
        // However, we cannot use prank for the admin because the initializer sets lrtConfig, and
        // we must follow the actual code flow. The simplest approach:
        // - Deploy a benign access control mock that grants admin to address(this).
        // - Call c.initialize(address(benignConfig)) as address(this) to become admin.
        // - Call c.updateLRTConfig(address(advConfig)) as address(this) (admin) to set the
        //   adversarial config as the current lrtConfig.
        // - Then prank as `caller` and attempt c.updateLRTConfig(newConfig). Because now the
        //   lrtConfig is advConfig which always returns false for hasRole, the reference must
        //   revert, while the mutant (with deleted check) succeeds.
        // This still lets the fuzzer choose `caller` and `newConfig`.

        BenignConfig benign = new BenignConfig();
        vm.prank(address(this));
        c.initialize(address(benign));

        // Now address(this) has admin rights on benign config, so we can updateLRTConfig to advConfig
        vm.prank(address(this));
        c.updateLRTConfig(address(advConfig));

        // At this point, c.lrtConfig() == advConfig. Any caller is denied admin role.
        // The reference modifier should revert; the mutant allows anyone.
        bool referenceReverted;
        vm.prank(caller);
        try c.updateLRTConfig(newConfig) {
            referenceReverted = false;
        } catch {
            referenceReverted = true;
        }

        // The universal property: for any caller without admin role, updateLRTConfig must revert.
        // The bug breaks this by allowing a non-admin to change the config, i.e., the call does not revert.
        assertTrue(referenceReverted);
    }
}

// Minimal adversarial access control contract that always returns false for hasRole.
contract AdversarialConfig {
    function hasRole(bytes32, address) external pure returns (bool) {
        return false;
    }

    // Other interface stubs that may be needed by the contract during initialization
    function isSupportedAsset(address) external pure returns (bool) {
        return false;
    }

    function rsETH() external pure returns (address) {
        return address(0);
    }

    function assetStrategy(address) external pure returns (address) {
        return address(0);
    }

    function getLSTToken(bytes32) external pure returns (address) {
        return address(0);
    }

    function getContract(bytes32) external pure returns (address) {
